import{_ as i,a0 as P,w as u,s as a,ao as s,I as r,x as o,a1 as n,A as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const L=JSON.parse('{"title":"戴文的Linux內核專題：12 配置內核(8) | LCTT x X-CMD","titleTemplate":false,"description":"戴文的Linux內核專題：12 配置內核(8) | LCTT (The Linux Kernel) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"戴文的Linux內核專題：12 配置內核(8) | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"戴文的Linux內核專題：12 配置內核(8) | LCTT (The Linux Kernel) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"The Linux Kernel/12 The Linux Kernel--Configuring the Kernel Part 8","title":"戴文的Linux內核專題：12 配置內核(8)","tag":"The Linux Kernel","desc":""},"relativePath":"The Linux Kernel/12 The Linux Kernel--Configuring the Kernel Part 8.md","filePath":"[post].md"}'),l={name:"The Linux Kernel/12 The Linux Kernel--Configuring the Kernel Part 8.md"};function I(T,t,v,C,d,m){const e=P("Link");return u(),a("div",null,[t[11]||(t[11]=s('<h1 id="戴文的linux內核專題-12-配置內核-8" tabindex="-1">戴文的Linux內核專題：12 配置內核(8) <a class="header-anchor" href="#戴文的linux內核專題-12-配置內核-8" aria-label="Permalink to “戴文的Linux內核專題：12 配置內核(8)”">​</a></h1><p><img src="http://www.linux.org/attachments/slide-jpg.484/" alt=""></p><p>在本篇中，我們將繼續配置網絡特性。記住，網絡是計算機最重要的特性，這篇文章和這之後的網絡相關文章都要重點了解。</p><p>在我們開啓這系列之前，我先要澄清一些事情。配置進程不會編輯你當前系統的內核。這個進程配置的是你編譯(或者交叉編譯)新內核前的源代碼。一旦我完成了配置過程，那麼我會討論讀者建議的話題。同樣，作為提醒，每個段落中在引號或者括號中的第一句或者第二句(很少)的文本是配置工具中設置的名字。</p><p>首先，我們可以啓用兩個不同的稀疏型獨立協議組播路由協議(&quot;IP: PIM-SM version 1 support&quot; 和 &quot;IP: PIM-SM version 2 support&quot;)，組播有點像廣播，但是廣播會給所有計算機發送信號而組播只會給選定的組或者計算機發送信號。所有PIM協議都是工作在IP的組播路由協議。</p><p>注意：當計算機與另外一台計算機或者服務器通信時，這叫做單播 - 只是以防你們想知道。</p><p>下一個要配置的網絡特性是&quot;ARP daemon support&quot;。這讓內核有一張IP地址表以及它們相應的在內部緩存中的硬件地址。ARP代表的是地址解析協議(Address-Resolution-Protocol)。</p><p>為了額外的安全，&quot;TCP syncookie support&quot;應該要啓用。這保護計算機免於受到SYN洪水攻擊。黑客或者惡意軟件可能會發送SYN信息給一台服務器來消耗它的資源，以便讓真實的訪客無法使用服務器提供的服務。SYN消息會打開一個計算機和服務器之間的連接。Syncookie會阻斷不正當的SYN消息。那麼，真實的用户可以仍舊訪問訪問網站，而黑客則沒辦法浪費你的帶寬。服務器應該啓用這個特性。</p><p>下面的特性是用於 &quot;Virtual (secure) IP: tunneling&quot;。隧道是一個網絡協議到另外一個網絡協議的封裝。當在使用虛擬私人網絡(VPN)時需要使用安全隧道。</p><p>接下來，啓用&quot;AH transformation&quot;增加對IPSec驗證頭的支持。這是一種管理數據驗證的安全措施。</p><p>在這之後，啓用&quot;ESP transformation&quot;增加對IPSec封裝安全協議的支持。這是加密與可選擇的數據驗證的安全措施。</p><p>如果啓用了這個特性(IP: IPComp transformation)，Linux內核會支持IP負載壓縮協議。這是一種無損壓縮系統。無損指的是數據仍會保持完整，在解壓縮後，數據在壓縮前後沒有變化。壓縮在加密前先執行。由於更少的數據傳輸，所以這個壓縮協議可以加速網絡。</p><p>下面三個設置用於處理不同的IPsec特性(&quot;IP: IPsec transport mode&quot;、&quot;IP: IPsec tunnel mode&quot;和&quot;IP: IPsec BEET mode&quot;)。IPSec代表的是因特網安全協議(Internet Protocol SECurity).兩台計算機之間並且/或者服務器間的傳輸模式是默認的IPSec模式。傳輸模式使用AH或者ESP頭並且只加密IP頭。在隧道模式下，IP頭和負載會被加密。隧道模式通常用於連接網關到服務器/服務器或者服務器到服務器。BEET模式(Bound End-to-End Tunnel)不會在IP地址改變時重連。BEET模式下的連接會仍然存在。BEET模式比其他幾種模式使用更少的字節。</p><p>下面，內核可以支持收到大量IPv4/TCP包時減輕棧負擔(Large Receive Offload (ipv4/tcp))。網卡(NIC)處理TCP/IP棧。這個特性在內核中增加了處理大型棧的代碼。</p><p>INET套接字可以啓用(INET: socket monitoring interface)。INET套接字用於因特網。這個特性(當啓用時)會監視來自或者發往因特網的連接與流量。</p><p>這裏有另外一個套接字監視接口(UDP: socket monitoring interface)。這個用於用户數據報協議(User Datagram Protocol (UDP))。再説一下，這個特性監視UDP的套接字。</p><p>以下的設定會啓用不同的TCP擁塞控制(TCP: advanced congestion control)。如果網絡變得太忙或者帶寬已滿，那麼許多計算機必須等待一些帶寬或者它們的數據流會變慢。如果流量被合理管理，這回有助於網絡性能提升。</p><p>TCP連接可以被MD5保護(TCP: MD5 Signature Option support)。這用於保護核心路由器之間的邊界網關協議(Border Gateway Protocol (BGP))連接。核心路由器是網絡中主要的路由器；這些路由器有時指的是因特網/網絡的骨幹。BGP是一種路由決策協議。</p><p>下一個設定允許你啓用/禁用&quot;The IPv6 protocol&quot;。當你啓用它，IPv4仍舊可以很好地工作。</p><p>下面的特性是一個特殊的隱私特性(IPv6: Privacy Extensions (RFC 3041) support)。這使得系統在網絡接口中生成並使用不同的隨即地址。</p><p>注意：計算機中沒有數據是真正隨機的。計算機中隨機數和隨機字串通常稱為偽隨機。</p><p>在多路由的網絡中，這個特性允許系統能夠更有效地計算出該使用哪一個(IPv6: Router Preference (RFC 4191))。</p><p>在這之後，一個用於處理路由信息的實驗性特性可以啓用/禁用(IPv6: Route Information (RFC 4191))。記住，在編譯一個穩定內核時，除非你確實需要這個問題中特性，才去安裝實驗性的功能。</p><p>有時，當系統自動配置它的IPv6地址時，它可能會得到一個網絡中已被使用的IPv6地址。這是一個允許重複地址檢測(Duplicate Address Detection (DAD)的實驗性特性(IPv6: Enable RFC 4429 Optimistic DAD)。</p><p>IPv6可以有不同的IPsecc特性支持(&quot;IPv6: AH transformation&quot; 和 &quot;IPv6: ESP transformation&quot;)。</p><p>IPv6同樣可以使用先前討論過的IP負載壓縮協議(IP Payload Compression Protocol)(IPv6: IPComp transformation)。</p><p>這裏甚至有IPv6移動支持(IPv6: Mobility)。這允許使用IPv6的移動設備在保留同樣地址的情況下使用其他的網絡。</p><p>再説一次，這裏同樣有一些針對IPv6的IPsec特性(&quot;IPv6: IPsec transport mode&quot;、&quot;IPv6: IPsec tunnel mode&quot;、&quot;IPv6: IPsec BEET mode&quot;)。</p><p>當啓用此項後，IPv6可以支持MIPv6路由優化(IPv6: MIPv6 route optimization mode)。這樣就可以確保最短和最佳網絡路徑了。如果消息在更少的路由和網絡設備間發送，那麼下載和上傳速度就可以更快。</p><p>如果一個管理員需要連接到兩個IPv6網絡，但是隻能通過IPv4來連接，這時內核使這個變得可能(IPv6: IPv6-in-IPv4 tunnel (SIT driver)。這通過隧道使IPv6報文穿越IPv4網絡。</p><p>這個隧道特性是用於IPv6-in-IPv6 和 IPv4 tunneled in IPv6 (IPv6: IP-in-IPv6 tunnel (RFC2473))</p><p>另外一個隧道特性是(IPv6: GRE tunnel)。他只允許GRE隧道。(GRE：通用路由封裝(Generic Routing Encapsulation))</p><p>允許支持多重路由表(IPv6: Multiple Routing Tables)。路由表是一張網絡位置列表和數據要去目的地的路徑。</p><p>允許根據源地址或前綴進行路由如果啓用了(IPv6: source address based routing)。</p><p>&quot;IPv6 Multicast routing&quot;(IPv6組播路由)仍然是實驗性質。IPv4和IPv6處理組播的方式不同。</p><p>典型的組播路由根據目標地址和源地址來處理組播包(IPv6: multicast policy routing)。啓用這個選項會將接口和包的標記(mark)包含到決策中。</p><p>下面可以啓用IPv6的PIM-SMv2 組播路由協議(IPv6: PIM-SM version 2 support)。這與先前提到的IPv4 PIM相同。因為IPv4和IPv6不同，所以PIM可以被v4/v6同時/分別激活</p><p>網絡包標籤協議(Network packet labeling protocols)(就像CIPSO和RIPSO)可以啓用(NetLabel subsystem support)。這些標籤包含了安全信息和權限。</p><p>網絡包可以通過啓用安全標記(Security Marking)變得更安全。</p><p>這個網絡特性增加了一些開銷(Time-stamping in PHY devices)。物理層(PHY)設備可以給網絡包打上時間戳。PHY代表的是&quot;PHYsical layer&quot;。這些設備管理收到和發送的消息。</p><p>可以啓用netfilter(Network packet filtering framework)。Netfilters過濾並修改過往的網絡包。包過濾器是一種防火牆。如果包滿足了一定的條件，包不會被允許通過。</p><p>數據報擁塞控制協議(Datagram Congestion Control Protocol)可以啓用(The DCCP Protocol)。DCCP允許雙向單播連接。DCCP有助於流媒體、網絡電話和在線遊戲。</p><p>下一步，流控制傳輸協議(Stream Control Transmission Protocol)可以啓用(The SCTP Protocol)。SCTP工作在IP頂層並且是一個穩定可靠的協議。</p><p>下面的協議是可靠數據報套接字(Reliable Datagram Sockets)協議(The RDS Protocol)。</p><p>RDS可以使用Infiniband和iWARP作為一種支持RDMA的傳輸方式(RDS over Infiniband and iWARP)，Infiniband和iWARP都是協議。RDMA代表的是遠程直接內存訪問(remote direct memory access)。RDMA用於一台遠程計算機訪問另一台計算機的內存而無需本機計算機操作系統的輔助。這就像直接內存訪問(DMA),但是這裏遠程代替了本地計算機。</p><p>RDS同樣可以使用TCP傳輸(RDS over TCP)</p><p>接下來，&quot;RDS debugging messages&quot;應該禁用。</p><p>下面的網絡協議用於集羣(The TIPC Protocol)。集羣就是一組計算機作為一台計算機。它們需要有一個方式去通信，所以他們使用透明內部進程間通信協議(Transparent Inter Process Communication (TIPC))。</p><p>這個高速協議使用固定大小的數據包(Asynchronous Transfer Mode (ATM))。</p><p>使用ATM的IP可以與連接到一個ATM網絡的IP的系統通信(Classical IP over ATM)。</p><p>下一個特性禁用&quot;ICMP host unreachable&quot;(ICMP主機不可達)錯誤信息(Do NOT send ICMP if no neighbor)。這防止了由於重新校驗而移除ATMARP表被移除的問題。ATMARP表管理地址解析。ICMP代表的是因特網控制消息協議(Internet Control Message Protocol)並被常用於通過網絡發送錯誤消息。</p><p>LAN仿真(LANE)仿真了ATM網絡上的LAN服務(LAN Emulation (LANE) support)。一台LANE計算機可以作為橋接Ethernet和ELAN的代理。</p><p>&quot;Multi-Protocol Over ATM (MPOA) support&quot;允許ATM設備通過子網邊界發送連接。</p><p>在這個特性下，至少在kernel看來ATM PVCs的行為就像Ethernet(RFC1483/2684 Bridged protocols）。PVC代表的是永久虛電路(permanent virtual circuit)。虛擬連接是一種基於包的連接，它伴隨着主/原始協議使用其他更高層的協議。</p><p>&quot;Layer Two Tunneling Protocol (L2TP)&quot;(二層隧道協議)是隧道對應用透明。虛擬私有網絡(Virtual Private Networks (VPNs))使用L2TP</p><p>要想使用基於Linux的以太網橋，啓用這個橋特性(802.1d Ethernet Bridging)。在網絡中，一個橋同時連接兩個或者更多的連接。以太網橋是使用以太網端口的硬件橋。</p><p>&quot;IGMP/MLD snooping&quot;(IGMP/MLD 探聽)是一種以太網橋能夠基於IGMP/MLD負載選擇性地轉發組播信號的能力。禁用這個特性能夠明顯減少內核的大小。IGMP代表的是因特網組管理協議(Internet Group Management Protocol),這是一種被用於設置組播組的協議。MLD代表多播監聽發現(Multicast Listener Discovery)。</p><p>下一個過濾特性允許以太網橋選擇性地管理在每個數據包中的基於VLAN的信息的流量。禁用這個特性可以減小內核的大小。</p><p>通過啓用這個特性(802.1Q VLAN Support)，VLAN接口可以在以太網上創建。下面&quot;GVRP (GARP VLAN Registration Protocol)&quot;支持GVPR協議被用於在網絡設備上註冊某些vlan。</p><p>在這之後，&quot;MVRP (Multiple VLAN Registration Protocol) support&quot;(多重VLAN註冊協議)可以啓用。MVRP是GVRP更新的替代品。</p><p>&quot;DECnet Support&quot;是一種Digital公司發明的網絡協議。這是一中既安全又穩定的協議。</p><p>&quot;DECnet router support&quot;允許用户製作基於Linux的支持DRCnet的路由。</p><p>注意：Linux可以用於服務器、工作站、路由器、集羣、防火牆並支持其他許多用途。</p><p>下面的特性用於支持邏輯鏈路層2(Logical Link Layer type 2)(ANSI/IEEE 802.2 LLC type 2 Support)。這層允許在同一個網絡設備上使用多個協議。強烈建議在網絡很重要的環境中啓用這個特性。最好所有內核都支持這個特性。</p><p>在下一篇文章中，我們將討論更多的關於可以配置的網絡設定。</p><hr>',66)),r("p",null,[t[1]||(t[1]=o("via: ",-1)),n(e,{href:"http://www.linux.org/threads/the-linux-kernel-configuring-the-kernel-part-8.4525/"},{default:p(()=>[...t[0]||(t[0]=[o("http://www.linux.org/threads/the-linux-kernel-configuring-the-kernel-part-8.4525/",-1)])]),_:1})]),r("p",null,[t[4]||(t[4]=o("譯者：",-1)),n(e,{href:"https://github.com/geekpi"},{default:p(()=>[...t[2]||(t[2]=[o("geekpi",-1)])]),_:1}),t[5]||(t[5]=o(" 校對：",-1)),n(e,{href:"https://github.com/wxy"},{default:p(()=>[...t[3]||(t[3]=[o("wxy",-1)])]),_:1})]),r("p",null,[t[8]||(t[8]=o("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[6]||(t[6]=[o("LCTT",-1)])]),_:1}),t[9]||(t[9]=o(" 原創翻譯，",-1)),n(e,{href:"http://linux.cn/"},{default:p(()=>[...t[7]||(t[7]=[o("Linux中國",-1)])]),_:1}),t[10]||(t[10]=o(" 榮譽推出",-1))])])}const M=i(l,[["render",I]]);export{L as __pageData,M as default};
